/**
 * Forma de una entrada del catálogo de modelos (ADR-007 1.7.0, `ModelCatalog`):
 * qué modelo, variante, revisión y cuantización están declarados, con lo que
 * hace falta para resolverlo sin volver a leer el artefacto.
 *
 * Es el contrato compartido entre el catálogo (TASK-THYROX-0697), que la
 * valida y la persiste, y el resolver (TASK-THYROX-0698), que la consume. No
 * dice nada de residencia ni de dispositivo: eso es del scheduler.
 */

import type { AttentionShape, KvCacheType } from './memoryEstimate.js'
import type { ModelSource } from './modelName.js'
import type { QuantizationLevel } from './quantizationLevel.js'

export type { AttentionShape }

/**
 * Dónde vive el artefacto: un GGUF propio, un modelo del registro de Ollama o
 * un snapshot de safetensors que carga Transformers (TASK-THYROX-0776); el
 * `artifactId` de un snapshot es el sha256 de su manifiesto.
 */
export type ArtifactFormat = 'gguf' | 'ollama-registry' | 'safetensors'

/** Capacidades que una petición puede exigir al modelo. */
export type ModelCapability = 'completion' | 'tools' | 'embeddings'

/** Digest y tamaño exactos del artefacto que se sirve. */
export interface CatalogArtifact {
  readonly format: ArtifactFormat
  /** 64 hex en minúsculas, sin prefijo `sha256:`. */
  readonly sha256: string
  readonly bytes: number
}

export interface ModelCatalogEntry {
  /** Nombre contractual `thyrox-<org>--<repo>:<quant>-<source>-<revision12>`. */
  readonly name: string
  readonly repository: string
  readonly source: ModelSource
  /** Revisión completa: commit de HF (40 hex) o digest del manifiesto (64 hex). */
  readonly revision: string
  readonly quantization: QuantizationLevel
  readonly artifact: CatalogArtifact
  /** `general.architecture` del GGUF. */
  readonly architecture: string
  /** Extraída de la metadata GGUF al declarar (`attentionShapeOf`): basta para estimar la caché KV sin releer el archivo. */
  readonly attention: AttentionShape
  /** `<arch>.context_length`: el máximo que el modelo admite. */
  readonly maxContextLength: number
  readonly defaultKvCacheType: KvCacheType
  readonly capabilities: readonly ModelCapability[]
  /** Instante ISO 8601 en UTC en que se declaró la entrada. */
  readonly declaredAt: string
}

/**
 * `ensureModel(name, deps)`: el reconciliador idempotente que deja disponible
 * un modelo del catálogo en un runtime (TASK-THYROX-0729). No es
 * `download()+install()`: cada paso mide el estado y actúa sólo si no es el
 * pedido, así que la segunda llamada no descarga ni instala.
 *
 * Responde una sola pregunta —¿puede este runtime servir este modelo
 * concreto?—. No decide GPU, instancia, residencia ni endpoint
 * (TASK-THYROX-0703).
 *
 * READY exige tres digests iguales, cada uno medido: el sha256 del catálogo,
 * el del GGUF materializado (el que `materializeArtifact` midió sobre el
 * archivo antes de publicarlo en la caché) y el contenido que el runtime resuelve para el nombre después de
 * cualquier instalación. Un instalador que responde `installed` y sirve otra
 * cosa no deja READY. `downloaded` e `installed` dicen lo que ocurrió en esta
 * llamada, no lo que se supone.
 */
import type { CatalogArtifact, ModelCatalogEntry } from '@thyrox/model-artifacts/catalogEntry.ts'
import type { ModelArtifactResolver, PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'

import { materializeArtifact, type ArtifactFetcher } from './modelArtifactCache.js'
import type { InstalledModelState, ModelInstaller } from './modelInstaller.js'

/** La parte del catálogo que el reconciliador consulta. */
export interface CatalogLookup {
  byName(name: string): ModelCatalogEntry | undefined
}

export interface EnsureModelDependencies {
  readonly catalog: CatalogLookup
  readonly resolver: ModelArtifactResolver
  readonly fetcher: ArtifactFetcher
  readonly installer: ModelInstaller
  readonly cacheDir: string
}

/** Los tres digests cuya igualdad es READY. */
export interface ReadinessEvidence {
  readonly catalogSha256: string
  readonly materializedSha256: string
  /** Vacío si el runtime no resuelve el nombre: nunca coincide con un sha256. */
  readonly runtimeSha256: string
}

/** Dónde se detuvo una reconciliación fallida. */
export type EnsureStage = 'materialize' | 'install' | 'verify'

export type EnsureOutcome =
  | { readonly status: 'ready'; readonly name: string; readonly evidence: ReadinessEvidence; readonly downloaded: boolean; readonly installed: boolean }
  | { readonly status: 'not_declared'; readonly name: string }
  | { readonly status: 'not_materializable'; readonly name: string; readonly reason: string }
  | { readonly status: 'failed'; readonly name: string; readonly stage: EnsureStage; readonly reason: string; readonly downloaded: boolean; readonly installed: boolean }

/** Un GGUF verificado en la caché y lo que costó tenerlo. */
interface Materialized {
  readonly path: string
  readonly sha256: string
  readonly downloaded: boolean
}

/** Lo que el runtime resuelve tras reconciliar, y si hubo que instalar. */
interface Reconciled {
  readonly state: InstalledModelState | undefined
  readonly installed: boolean
}

type StepResult<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly reason: string }

export async function ensureModel(name: string, deps: EnsureModelDependencies): Promise<EnsureOutcome> {
  const entry = deps.catalog.byName(name)
  if (entry === undefined) return { status: 'not_declared', name }
  const resolution = await deps.resolver.resolve(entry.artifact)
  if (resolution.status !== 'resolved') return { status: 'not_materializable', name, reason: resolution.reason }

  const materialized = await materialize(entry.artifact, resolution.pinned, deps)
  if (!materialized.ok) return { status: 'failed', name, stage: 'materialize', reason: materialized.reason, downloaded: false, installed: false }
  const { downloaded } = materialized.value

  const reconciled = await reconcileRuntime(name, materialized.value, deps.installer)
  if (!reconciled.ok) return { status: 'failed', name, stage: 'install', reason: reconciled.reason, downloaded, installed: false }
  const { installed, state } = reconciled.value

  const evidence = { catalogSha256: entry.artifact.sha256, materializedSha256: materialized.value.sha256, runtimeSha256: state?.contentSha256 ?? '' }
  if (!isReady(evidence)) return { status: 'failed', name, stage: 'verify', reason: mismatchReason(name, evidence), downloaded, installed }
  return { status: 'ready', name, evidence, downloaded, installed }
}

async function materialize(artifact: CatalogArtifact, pinned: PinnedModelArtifact, deps: EnsureModelDependencies): Promise<StepResult<Materialized>> {
  const outcome = await materializeArtifact({ artifact, pinned, cacheDir: deps.cacheDir, fetcher: deps.fetcher })
  if ('reason' in outcome) return { ok: false, reason: outcome.reason }
  // `materializeArtifact` sólo devuelve `cached`/`fetched` tras medir el
  // sha256 del archivo publicado: ese es el digest materializado.
  return { ok: true, value: { path: outcome.path, sha256: outcome.sha256, downloaded: outcome.status === 'fetched' } }
}

/** Instala sólo si el runtime no resuelve el nombre al contenido materializado, y vuelve a inspeccionar. */
async function reconcileRuntime(name: string, materialized: Materialized, installer: ModelInstaller): Promise<StepResult<Reconciled>> {
  const current = await installer.inspect(name)
  if (servesContent(current, materialized.sha256)) return { ok: true, value: { state: current, installed: false } }
  const outcome = await installer.install({ name, artifactPath: materialized.path, contentSha256: materialized.sha256 })
  if (outcome.status !== 'installed') return { ok: false, reason: outcome.reason }
  return { ok: true, value: { state: await installer.inspect(name), installed: true } }
}

function servesContent(state: InstalledModelState | undefined, sha256: string): boolean {
  return state?.contentSha256 === sha256
}

function isReady(evidence: ReadinessEvidence): boolean {
  return evidence.catalogSha256 === evidence.materializedSha256 && evidence.materializedSha256 === evidence.runtimeSha256
}

function mismatchReason(name: string, evidence: ReadinessEvidence): string {
  const runtime = evidence.runtimeSha256 === '' ? 'nada' : `sha256:${evidence.runtimeSha256}`
  return `${name}: el catálogo declara sha256:${evidence.catalogSha256}, la caché tiene sha256:${evidence.materializedSha256} y el runtime resuelve ${runtime}`
}

/**
 * Materialización verificada de un artefacto de modelo en la caché local
 * (TASK-THYROX-0729).
 *
 * La caché es reconstruible y no es autoridad: la autoridad es el artefacto
 * permanente, y el contenido válido es el que tiene el sha256 que el catálogo
 * declara. Por eso una entrada en caché se vuelve a verificar antes de usarla,
 * y una que no coincide se descarta y se reconstruye.
 *
 * La descarga escribe en un temporal hermano y sólo un `rename` atómico tras
 * verificar el sha256 la publica en la ruta por digest que leen los
 * consumidores: una descarga cortada o con otro contenido nunca parece un
 * GGUF materializado. Quién descarga es un `ArtifactFetcher`: en producción,
 * un trabajo de la primitiva de Podman sin credencial.
 */
import { mkdir, rename, rm, stat } from 'node:fs/promises'
import { join } from 'node:path'

import type { CatalogArtifact } from '@thyrox/model-artifacts/catalogEntry.ts'
import type { PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'

import { sha256OfFile } from './sha256File.js'

export type FetchOutcome =
  | { readonly status: 'fetched' }
  | { readonly status: 'failed'; readonly reason: string }

/** Escribe el blob GGUF de `pinned` en `destination`; no verifica ni publica nada. */
export interface ArtifactFetcher {
  fetch(pinned: PinnedModelArtifact, destination: string): Promise<FetchOutcome>
}

export type MaterializationOutcome =
  | { readonly status: 'cached' | 'fetched'; readonly path: string; readonly sha256: string }
  | { readonly status: 'rejected' | 'failed'; readonly reason: string }

export interface MaterializationRequest {
  readonly artifact: CatalogArtifact
  readonly pinned: PinnedModelArtifact
  readonly cacheDir: string
  readonly fetcher: ArtifactFetcher
}

/** La única ruta que un consumidor lee: el GGUF verificado, nombrado por su contenido. */
export function cachedArtifactPath(cacheDir: string, sha256: string): string {
  return join(cacheDir, `sha256-${sha256}.gguf`)
}

/** El sha256 medido del archivo, o `undefined` si no existe. */
async function measuredSha256(path: string): Promise<string | undefined> {
  try {
    await stat(path)
  } catch {
    return undefined
  }
  return sha256OfFile(path)
}

export async function materializeArtifact(request: MaterializationRequest): Promise<MaterializationOutcome> {
  const { artifact, pinned, cacheDir } = request
  if (pinned.blobDigest !== `sha256:${artifact.sha256}`) {
    return { status: 'rejected', reason: `el artefacto fijado apunta a ${pinned.blobDigest}, no al contenido sha256:${artifact.sha256} del catálogo` }
  }
  const path = cachedArtifactPath(cacheDir, artifact.sha256)
  // El sha256 que se devuelve es el MEDIDO sobre el archivo, no el declarado:
  // es la segunda igualdad de READY y no puede ser una copia del catálogo.
  const cached = await measuredSha256(path)
  if (cached === artifact.sha256) return { status: 'cached', path, sha256: cached }

  await mkdir(cacheDir, { recursive: true })
  await rm(path, { force: true })
  const partial = join(cacheDir, `.partial-${artifact.sha256}-${process.pid}-${Date.now()}`)
  try {
    const fetched = await request.fetcher.fetch(pinned, partial)
    if (fetched.status !== 'fetched') return { status: 'failed', reason: fetched.reason }
    const actual = await sha256OfFile(partial)
    if (actual !== artifact.sha256) return { status: 'rejected', reason: `se descargó sha256:${actual}, el catálogo declara sha256:${artifact.sha256}` }
    await rename(partial, path)
    return { status: 'fetched', path, sha256: actual }
  } finally {
    await rm(partial, { force: true })
  }
}

#!/usr/bin/env bun
/**
 * `local-models-ensure <nombre-del-catálogo>`: deja el modelo disponible en
 * el Ollama gestionado bajo su nombre contractual (TASK-THYROX-0729).
 *
 * Es el cableado de producción de `ensureModel`: catálogo y índice de
 * ubicaciones de la instalación, descarga por digest con un trabajo de la
 * primitiva de Podman sin credencial, caché verificada en el hogar de
 * artefactos e instalación por el adaptador de Ollama, también como trabajo
 * de la primitiva. No decide residencia, GPU ni ruteo (TASK-THYROX-0703).
 *
 * Imprime el resultado en JSON por stdout. Salida: 0 READY · 1 fallo en una
 * etapa (la etapa y la causa van en el JSON) · 2 rehusado (no declarado, no
 * materializable, infraestructura o imagen ausentes).
 */
import { spawnSync } from 'node:child_process'
import { mkdir } from 'node:fs/promises'
import { join } from 'node:path'

import { JOB_EGRESS_ENV, resolveJobEgress } from '@thyrox/artifact-registry/jobEgress.ts'
import { localArtifactHome, localModelHome } from '@thyrox/model-artifacts/localModelHome.ts'
import { createIndexedArtifactResolver, loadArtifactLocationIndex } from '@thyrox/model-artifacts/modelArtifactResolver.ts'
import { loadModelCatalog } from '@thyrox/model-artifacts/modelCatalog.ts'
import { productionDeclarations, thyroxRoot } from '@thyrox/paths/reach.ts'
import { createPodmanExecutor } from '@thyrox/podman-execution/podmanExecutor.ts'
import { inspectImage } from '@thyrox/podman-execution/podmanObservation.ts'

import { ensureModel, type EnsureOutcome } from '../ensureModel.js'
import { infrastructureEnsureCommand, OLLAMA_CONTAINER, requireInfrastructure } from '../infrastructureReadiness.js'
import { OllamaModelInstaller } from '../ollamaModelInstaller.js'
import { createPodmanArtifactFetcher } from '../podmanArtifactFetcher.js'

const READY = 0
const FAILED = 1
const REFUSED = 2
/** La misma imagen neutra que el verificador de publicación: sólo aporta un userland donde montar `bun`. */
const JOB_IMAGE_ENV = 'THYROX_ARTIFACT_VERIFIER_IMAGE'
const DEFAULT_JOB_IMAGE = 'docker.io/library/ubuntu:24.04'
const RUNTIME_HOME_KEY = 'THYROX_RUNTIME_DIR'
const JOB_LIMITS = { cpus: 1, memoryMib: 1024, pidsLimit: 128 }

function refuse(message: string): never {
  process.stderr.write(`local-models-ensure: ${message}\n`)
  process.exit(REFUSED)
}

const [name, ...extra] = process.argv.slice(2)
if (name === undefined || name.startsWith('-') || extra.length > 0) refuse('uso: local-models-ensure <nombre-del-catálogo>')

const root = thyroxRoot()
const declarations = productionDeclarations()
const declared = (key: string): string | undefined => declarations.declared(key) ?? undefined
/** Como `local-models-catalog`: las variables de hogar y de Ollama se leen del entorno del proceso. */
const environment = process.env
const podman = createPodmanExecutor()

/** La ruta de un hogar la decide el registro de P11 (`paths/declarations.py`), no una copia de su default. */
function registeredHome(key: string): string {
  const resolved = spawnSync('bash', [join(root, 'bin', 'ensure_homes'), '--resolve', key], { encoding: 'utf8' })
  const path = resolved.stdout.trim()
  if (resolved.status !== 0 || !path) refuse(`no se resolvió el hogar ${key}: ${resolved.stderr.trim() || `exit ${resolved.status}`}`)
  return path
}

const imageRef = declared(JOB_IMAGE_ENV) || DEFAULT_JOB_IMAGE
const image = (await inspectImage(podman, imageRef))?.id
if (!image) refuse(`la imagen de trabajo ${imageRef} no está local (no se descarga implícitamente)`)

const egress = (() => {
  try {
    return resolveJobEgress({ ...process.env, [JOB_EGRESS_ENV.proxyUrl]: declared(JOB_EGRESS_ENV.proxyUrl), [JOB_EGRESS_ENV.caBundle]: declared(JOB_EGRESS_ENV.caBundle) })
  } catch (error) {
    refuse((error as Error).message)
  }
})()

try {
  await requireInfrastructure([OLLAMA_CONTAINER], infrastructureEnsureCommand(root))
} catch (error) {
  refuse((error as Error).message)
}

const owner = `model-ensure-${process.pid}`
const scratchDir = join(registeredHome(RUNTIME_HOME_KEY), 'model-install', owner)
await mkdir(scratchDir, { recursive: true })
const artifactHome = localArtifactHome(environment, root)
const jobOwner = { kind: 'lab' as const, id: owner, pid: process.pid }

const outcome: EnsureOutcome = await ensureModel(name, {
  catalog: await loadModelCatalog(localModelHome(environment, root).catalog),
  resolver: createIndexedArtifactResolver(await loadArtifactLocationIndex(artifactHome.artifactLocations)),
  cacheDir: artifactHome.artifactCache,
  fetcher: createPodmanArtifactFetcher({ podman, image, bunPath: process.execPath, repositoryRoot: root, egress, owner: jobOwner, workerId: `${owner}-fetch`, limits: JOB_LIMITS }),
  installer: new OllamaModelInstaller({ podman, image, bunPath: process.execPath, repositoryRoot: root, scratchDir, environment, owner: jobOwner, workerId: `${owner}-install`, limits: JOB_LIMITS }),
})

process.stdout.write(`${JSON.stringify(outcome)}\n`)
process.exit(outcome.status === 'ready' ? READY : outcome.status === 'failed' ? FAILED : REFUSED)

/**
 * La frontera entre identidad de contenido e identidad de distribución
 * (TASK-THYROX-0729).
 *
 * El catálogo declara QUÉ contenido necesita un modelo —`CatalogArtifact`:
 * formato, sha256 y bytes del GGUF— y no sabe dónde vive. El
 * `ModelArtifactResolver` responde DE DÓNDE se obtiene ese contenido: un
 * artefacto permanente fijado por el digest de su manifest, en un registry y
 * un repositorio. El registry no entra al catálogo.
 *
 * El índice de ubicaciones se busca sólo por digest de contenido: dos
 * artefactos con el mismo repositorio o tag nunca se confunden, y un tamaño
 * distinto del declarado no resuelve, porque entonces no es el mismo
 * contenido. Es puro: no lee red; su persistencia es un JSON canónico con
 * escritura atómica, como el catálogo.
 */
import { readFile, rename, rm, writeFile } from 'node:fs/promises'

import type { CatalogArtifact } from './catalogEntry.js'

/** Dónde se publicó un contenido: lo que registra una publicación verificada. */
export interface ArtifactLocation {
  /** 64 hex en minúsculas, sin prefijo: el sha256 del GGUF, igual al de `CatalogArtifact`. */
  readonly contentSha256: string
  readonly bytes: number
  readonly registry: string
  readonly repository: string
  /** `sha256:<64 hex>`: el manifest que contiene la capa. */
  readonly manifestDigest: string
}

/** La identidad de distribución inmutable de un artefacto de modelo. */
export interface PinnedModelArtifact {
  readonly registry: string
  readonly repository: string
  readonly manifestDigest: string
  /** `sha256:<64 hex>`: la capa que es el GGUF. */
  readonly blobDigest: string
  readonly bytes: number
}

export type ArtifactResolution =
  | { readonly status: 'resolved'; readonly pinned: PinnedModelArtifact }
  | { readonly status: 'not_materializable'; readonly reason: string }

export interface ModelArtifactResolver {
  resolve(artifact: CatalogArtifact): Promise<ArtifactResolution>
}

export class InvalidArtifactLocationError extends Error {
  constructor(field: string, value: unknown) {
    super(`ubicación de artefacto inválida: ${field} = ${JSON.stringify(value)}`)
    this.name = 'InvalidArtifactLocationError'
  }
}

export class ArtifactLocationConflictError extends Error {
  constructor(location: ArtifactLocation) {
    super(`el contenido ${location.contentSha256} ya está registrado en ${location.repository}@${location.manifestDigest} con otro tamaño`)
    this.name = 'ArtifactLocationConflictError'
  }
}

const SHA256_HEX = /^[0-9a-f]{64}$/
const OCI_DIGEST = /^sha256:[0-9a-f]{64}$/

function validated(location: ArtifactLocation): ArtifactLocation {
  if (!SHA256_HEX.test(location.contentSha256)) throw new InvalidArtifactLocationError('contentSha256', location.contentSha256)
  if (!Number.isInteger(location.bytes) || location.bytes <= 0) throw new InvalidArtifactLocationError('bytes', location.bytes)
  if (!location.registry) throw new InvalidArtifactLocationError('registry', location.registry)
  if (!location.repository) throw new InvalidArtifactLocationError('repository', location.repository)
  if (!OCI_DIGEST.test(location.manifestDigest)) throw new InvalidArtifactLocationError('manifestDigest', location.manifestDigest)
  return {
    bytes: location.bytes,
    contentSha256: location.contentSha256,
    manifestDigest: location.manifestDigest,
    registry: location.registry,
    repository: location.repository,
  }
}

function sameManifest(a: ArtifactLocation, b: ArtifactLocation): boolean {
  return a.contentSha256 === b.contentSha256 && a.registry === b.registry
    && a.repository === b.repository && a.manifestDigest === b.manifestDigest
}

function orderKey(location: ArtifactLocation): string {
  return [location.contentSha256, location.registry, location.repository, location.manifestDigest].join('\u0000')
}

/** Índice inmutable de ubicaciones, ordenado para que su JSON sea estable. */
export class ArtifactLocationIndex {
  private constructor(private readonly entries: readonly ArtifactLocation[]) {}

  static of(locations: readonly ArtifactLocation[]): ArtifactLocationIndex {
    return locations.reduce((index, location) => index.with(location), new ArtifactLocationIndex([]))
  }

  locations(): readonly ArtifactLocation[] {
    return this.entries
  }

  /** Añade una ubicación; la misma otra vez no cambia nada, y el mismo manifest con otro tamaño rehúsa. */
  with(location: ArtifactLocation): ArtifactLocationIndex {
    const candidate = validated(location)
    const existing = this.entries.find(entry => sameManifest(entry, candidate))
    if (existing) {
      if (existing.bytes !== candidate.bytes) throw new ArtifactLocationConflictError(candidate)
      return this
    }
    return new ArtifactLocationIndex([...this.entries, candidate].sort((a, b) => orderKey(a).localeCompare(orderKey(b))))
  }

  forContent(sha256: string): readonly ArtifactLocation[] {
    return this.entries.filter(entry => entry.contentSha256 === sha256)
  }
}

export function createIndexedArtifactResolver(index: ArtifactLocationIndex): ModelArtifactResolver {
  return {
    async resolve(artifact) {
      const candidates = index.forContent(artifact.sha256)
      if (candidates.length === 0) {
        return { status: 'not_materializable', reason: `ningún artefacto permanente registrado contiene ${artifact.sha256}` }
      }
      const location = candidates.find(candidate => candidate.bytes === artifact.bytes)
      if (!location) {
        return { status: 'not_materializable', reason: `el contenido ${artifact.sha256} está registrado con otro tamaño que los ${artifact.bytes} bytes del catálogo` }
      }
      return {
        status: 'resolved',
        pinned: {
          registry: location.registry,
          repository: location.repository,
          manifestDigest: location.manifestDigest,
          blobDigest: `sha256:${location.contentSha256}`,
          bytes: location.bytes,
        },
      }
    },
  }
}

/** Lee el índice; un archivo ausente es un índice vacío, uno inválido es un error con la ruta. */
export async function loadArtifactLocationIndex(path: string): Promise<ArtifactLocationIndex> {
  let text: string
  try {
    text = await readFile(path, 'utf8')
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return ArtifactLocationIndex.of([])
    throw error
  }
  const document = JSON.parse(text) as { locations?: ArtifactLocation[] }
  if (!Array.isArray(document.locations)) throw new InvalidArtifactLocationError(`${path}: locations`, document.locations)
  return ArtifactLocationIndex.of(document.locations)
}

/** Escribe el índice en un temporal hermano y lo renombra sobre la ruta. */
export async function saveArtifactLocationIndex(path: string, index: ArtifactLocationIndex): Promise<void> {
  const temporaryPath = `${path}.${process.pid}.${Date.now()}.tmp`
  try {
    await writeFile(temporaryPath, `${JSON.stringify({ locations: index.locations() }, null, 2)}\n`, { flag: 'wx' })
    await rename(temporaryPath, path)
  } finally {
    await rm(temporaryPath, { force: true })
  }
}

/**
 * Forma de una entrada del catálogo de modelos (ADR-007 1.7.0, `ModelCatalog`):
 * qué modelo, variante, revisión y cuantización están declarados, con lo que
 * hace falta para resolverlo sin volver a leer el artefacto.
 *
 * Es el contrato compartido entre el catálogo (TASK-THYROX-0697), que la
 * valida y la persiste, y el resolver (TASK-THYROX-0698), que la consume. No
 * dice nada de residencia ni de dispositivo: eso es del scheduler.
 */

import type { AttentionShape, KvCacheType } from './memoryEstimate.js'
import type { ModelSource } from './modelName.js'
import type { QuantizationLevel } from './quantizationLevel.js'

export type { AttentionShape }

/**
 * Dónde vive el artefacto: un GGUF propio, un modelo del registro de Ollama o
 * un snapshot de safetensors que carga Transformers (TASK-THYROX-0776); el
 * `artifactId` de un snapshot es el sha256 de su manifiesto.
 */
export type ArtifactFormat = 'gguf' | 'ollama-registry' | 'safetensors'

/** Capacidades que una petición puede exigir al modelo. */
export type ModelCapability = 'completion' | 'tools' | 'embeddings'

/** Digest y tamaño exactos del artefacto que se sirve. */
export interface CatalogArtifact {
  readonly format: ArtifactFormat
  /** 64 hex en minúsculas, sin prefijo `sha256:`. */
  readonly sha256: string
  readonly bytes: number
}

export interface ModelCatalogEntry {
  /** Nombre contractual `thyrox-<org>--<repo>:<quant>-<source>-<revision12>`. */
  readonly name: string
  readonly repository: string
  readonly source: ModelSource
  /** Revisión completa: commit de HF (40 hex) o digest del manifiesto (64 hex). */
  readonly revision: string
  readonly quantization: QuantizationLevel
  readonly artifact: CatalogArtifact
  /** `general.architecture` del GGUF. */
  readonly architecture: string
  /** Extraída de la metadata GGUF al declarar (`attentionShapeOf`): basta para estimar la caché KV sin releer el archivo. */
  readonly attention: AttentionShape
  /** `<arch>.context_length`: el máximo que el modelo admite. */
  readonly maxContextLength: number
  readonly defaultKvCacheType: KvCacheType
  readonly capabilities: readonly ModelCapability[]
  /** Instante ISO 8601 en UTC en que se declaró la entrada. */
  readonly declaredAt: string
}

/**
 * El reconciliador `ensureModel` (TASK-THYROX-0729): READY sólo cuando el
 * sha256 del catálogo, el del GGUF materializado y el contenido que el
 * runtime resuelve para el nombre son el mismo. Todo puerto es un fake: el
 * resolver, el fetcher y el instalador registran sus llamadas, así que las
 * descargas e instalaciones se cuentan, no se infieren.
 */
import { afterEach, beforeEach, describe, expect, test } from 'bun:test'
import { createHash } from 'node:crypto'
import { existsSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import type { ModelCatalogEntry } from '@thyrox/model-artifacts/catalogEntry.ts'
import { ModelCatalog } from '@thyrox/model-artifacts/modelCatalog.ts'
import { thyroxModelName } from '@thyrox/model-artifacts/modelName.ts'
import type { ModelArtifactResolver } from '@thyrox/model-artifacts/modelArtifactResolver.ts'

import { ensureModel, type EnsureModelDependencies } from '../ensureModel.js'
import { cachedArtifactPath, type ArtifactFetcher } from '../modelArtifactCache.js'
import type { InstallOutcome, ModelInstaller, ModelInstallRequest } from '../modelInstaller.js'

const CONTENT = 'GGUF-bytes-of-a-q4-model'
const SHA = createHash('sha256').update(CONTENT).digest('hex')
const OTHER_SHA = 'e'.repeat(64)
const REVISION = '7ae557604adf67be50417f59c2c2f167def9a775'
const NAME = thyroxModelName({ repository: 'Qwen/Qwen2.5-0.5B-Instruct', quantization: 'q4_k_m', source: 'hf', revision: REVISION })
const ENTRY: ModelCatalogEntry = {
  name: NAME,
  repository: 'Qwen/Qwen2.5-0.5B-Instruct',
  source: 'hf',
  revision: REVISION,
  quantization: 'q4_k_m',
  artifact: { format: 'gguf', sha256: SHA, bytes: CONTENT.length },
  architecture: 'qwen2',
  attention: { blockCount: 24, kvHeadCount: 2, headDimension: 64 },
  maxContextLength: 4096,
  defaultKvCacheType: 'f16',
  capabilities: ['completion', 'tools'],
  declaredAt: '2026-10-01T07:00:00Z',
}
const CATALOG = ModelCatalog.empty().with(ENTRY)
const MANIFEST = `sha256:${'5'.repeat(64)}`

let cacheDir: string
beforeEach(() => { cacheDir = mkdtempSync(join(tmpdir(), 'ensure-model-')) })
afterEach(() => rmSync(cacheDir, { recursive: true, force: true }))

const resolving: ModelArtifactResolver = {
  async resolve(artifact) {
    return { status: 'resolved', pinned: { registry: 'docker.io', repository: 'th3rox/lab', manifestDigest: MANIFEST, blobDigest: `sha256:${artifact.sha256}`, bytes: artifact.bytes } }
  },
}

const unresolving: ModelArtifactResolver = {
  async resolve() { return { status: 'not_materializable', reason: 'sin ubicación' } },
}

interface CountingFetcher extends ArtifactFetcher { readonly calls: string[] }

/** Un fetcher que escribe `content`; sin contenido, escribe un parcial y falla. */
function fetcherWriting(content: string | undefined): CountingFetcher {
  const calls: string[] = []
  return {
    calls,
    async fetch(pinned, destination) {
      calls.push(pinned.blobDigest)
      if (content === undefined) {
        writeFileSync(destination, CONTENT.slice(0, 5))
        return { status: 'failed', reason: 'conexión cortada' }
      }
      writeFileSync(destination, content)
      return { status: 'fetched' }
    },
  }
}

interface FakeRuntime extends ModelInstaller { readonly installs: ModelInstallRequest[] }

/**
 * Un runtime con un contenido inicial por nombre. `serves` decide qué guarda
 * al instalar: por defecto, lo pedido; un fallo devuelve `failed` sin tocarlo.
 */
function runtime(initial: string | undefined, behaviour: { serves?: string; fails?: boolean } = {}): FakeRuntime {
  let current = initial
  const installs: ModelInstallRequest[] = []
  return {
    installs,
    async inspect(name) {
      return current === undefined ? undefined : { name, contentSha256: current }
    },
    async install(request): Promise<InstallOutcome> {
      installs.push(request)
      if (behaviour.fails) return { status: 'failed', reason: 'el runtime rehusó el blob' }
      current = behaviour.serves ?? request.contentSha256
      return { status: 'installed' }
    },
  }
}

function deps(fetcher: CountingFetcher, installer: FakeRuntime, resolver = resolving): EnsureModelDependencies {
  return { catalog: CATALOG, resolver, fetcher, installer, cacheDir }
}

const EVIDENCE = { catalogSha256: SHA, materializedSha256: SHA, runtimeSha256: SHA }

describe('ensureModel', () => {
  test('un nombre fuera del catálogo es not_declared, sin resolver ni descargar', async () => {
    const fetcher = fetcherWriting(CONTENT)
    const outcome = await ensureModel('thyrox-nadie--nada:q4_k_m-hf-000000000000', deps(fetcher, runtime(undefined)))
    expect(outcome.status).toBe('not_declared')
    expect(fetcher.calls).toHaveLength(0)
  })

  test('1. sin distribución es not_materializable, sin descargar ni instalar', async () => {
    const fetcher = fetcherWriting(CONTENT)
    const installer = runtime(undefined)
    const outcome = await ensureModel(NAME, deps(fetcher, installer, unresolving))
    expect(outcome).toMatchObject({ status: 'not_materializable', reason: 'sin ubicación' })
    expect([fetcher.calls.length, installer.installs.length]).toEqual([0, 0])
  })

  test('2. caché vacía: una descarga, verifica, instala desde la caché y queda READY', async () => {
    const fetcher = fetcherWriting(CONTENT)
    const installer = runtime(undefined)
    const outcome = await ensureModel(NAME, deps(fetcher, installer))
    expect(outcome).toEqual({ status: 'ready', name: NAME, evidence: EVIDENCE, downloaded: true, installed: true })
    expect(fetcher.calls).toHaveLength(1)
    expect(installer.installs).toEqual([{ name: NAME, artifactPath: cachedArtifactPath(cacheDir, SHA), contentSha256: SHA }])
  })

  test('3. caché correcta: cero descargas', async () => {
    writeFileSync(cachedArtifactPath(cacheDir, SHA), CONTENT)
    const fetcher = fetcherWriting(CONTENT)
    const outcome = await ensureModel(NAME, deps(fetcher, runtime(undefined)))
    expect(outcome).toMatchObject({ status: 'ready', downloaded: false, installed: true })
    expect(fetcher.calls).toHaveLength(0)
  })

  test('4. caché con otro contenido: no se usa, se reconstruye', async () => {
    writeFileSync(cachedArtifactPath(cacheDir, SHA), 'otro contenido')
    const fetcher = fetcherWriting(CONTENT)
    const outcome = await ensureModel(NAME, deps(fetcher, runtime(undefined)))
    expect(outcome).toMatchObject({ status: 'ready', downloaded: true, evidence: EVIDENCE })
    expect(fetcher.calls).toHaveLength(1)
  })

  test('5. runtime vacío: instala', async () => {
    const installer = runtime(undefined)
    expect(await ensureModel(NAME, deps(fetcherWriting(CONTENT), installer))).toMatchObject({ status: 'ready', installed: true })
    expect(installer.installs).toHaveLength(1)
  })

  test('6. runtime con el contenido correcto: cero instalaciones', async () => {
    const installer = runtime(SHA)
    expect(await ensureModel(NAME, deps(fetcherWriting(CONTENT), installer))).toMatchObject({ status: 'ready', installed: false, evidence: EVIDENCE })
    expect(installer.installs).toHaveLength(0)
  })

  test('7. el mismo nombre con otro contenido no cuenta como READY: se reinstala', async () => {
    const installer = runtime(OTHER_SHA)
    const outcome = await ensureModel(NAME, deps(fetcherWriting(CONTENT), installer))
    expect(outcome).toMatchObject({ status: 'ready', installed: true, evidence: EVIDENCE })
    expect(installer.installs).toHaveLength(1)
  })

  test('8. un fallo de descarga es failed en materialize y no deja caché parcial válida', async () => {
    const installer = runtime(undefined)
    const outcome = await ensureModel(NAME, deps(fetcherWriting(undefined), installer))
    expect(outcome).toMatchObject({ status: 'failed', stage: 'materialize', reason: 'conexión cortada', downloaded: false, installed: false })
    expect(existsSync(cachedArtifactPath(cacheDir, SHA))).toBe(false)
    expect(readdirSync(cacheDir)).toEqual([])
    expect(installer.installs).toHaveLength(0)
  })

  test('8b. una descarga con otro contenido es failed en materialize, nunca READY', async () => {
    const outcome = await ensureModel(NAME, deps(fetcherWriting('contenido ajeno'), runtime(undefined)))
    expect(outcome).toMatchObject({ status: 'failed', stage: 'materialize' })
    expect(existsSync(cachedArtifactPath(cacheDir, SHA))).toBe(false)
  })

  test('9. un fallo de instalación es failed en install, nunca READY', async () => {
    const outcome = await ensureModel(NAME, deps(fetcherWriting(CONTENT), runtime(undefined, { fails: true })))
    expect(outcome).toMatchObject({ status: 'failed', stage: 'install', reason: 'el runtime rehusó el blob', downloaded: true, installed: false })
  })

  test('un instalador que dice installed pero sirve otro contenido no deja READY', async () => {
    const outcome = await ensureModel(NAME, deps(fetcherWriting(CONTENT), runtime(undefined, { serves: OTHER_SHA })))
    expect(outcome).toMatchObject({ status: 'failed', stage: 'verify', installed: true })
    expect(outcome.status === 'failed' && outcome.reason).toContain(OTHER_SHA)
  })

  test('10. la segunda llamada: cero descargas, cero instalaciones, READY con la misma evidencia', async () => {
    const fetcher = fetcherWriting(CONTENT)
    const installer = runtime(undefined)
    const first = await ensureModel(NAME, deps(fetcher, installer))
    const second = await ensureModel(NAME, deps(fetcher, installer))
    expect(second).toEqual({ status: 'ready', name: NAME, evidence: EVIDENCE, downloaded: false, installed: false })
    expect(first.status === 'ready' && first.evidence).toEqual(EVIDENCE)
    expect([fetcher.calls.length, installer.installs.length]).toEqual([1, 1])
  })
})

/**
 * Materialización verificada de un artefacto de modelo en la caché local
 * (TASK-THYROX-0729). La caché es reconstruible y no es autoridad: sólo vale
 * un archivo cuyo sha256 es el del catálogo, y una descarga incompleta o con
 * otro contenido nunca ocupa la ruta que los consumidores leen.
 */
import { afterEach, beforeEach, describe, expect, test } from 'bun:test'
import { createHash } from 'node:crypto'
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import type { CatalogArtifact } from '@thyrox/model-artifacts/catalogEntry.ts'
import type { PinnedModelArtifact } from '@thyrox/model-artifacts/modelArtifactResolver.ts'

import { cachedArtifactPath, materializeArtifact, type ArtifactFetcher } from '../modelArtifactCache.js'

const CONTENT = 'GGUF-bytes-of-a-q4-model'
const SHA = createHash('sha256').update(CONTENT).digest('hex')
const ARTIFACT: CatalogArtifact = { format: 'gguf', sha256: SHA, bytes: CONTENT.length }
const PINNED: PinnedModelArtifact = { registry: 'docker.io', repository: 'th3rox/lab', manifestDigest: `sha256:${'5'.repeat(64)}`, blobDigest: `sha256:${SHA}`, bytes: CONTENT.length }

let cacheDir: string
beforeEach(() => { cacheDir = mkdtempSync(join(tmpdir(), 'model-artifact-cache-')) })
afterEach(() => rmSync(cacheDir, { recursive: true, force: true }))

function fetcherWriting(content: string | undefined, calls: string[] = []): ArtifactFetcher & { calls: string[] } {
  return {
    calls,
    async fetch(pinned, destination) {
      calls.push(pinned.blobDigest)
      if (content === undefined) {
        writeFileSync(destination, CONTENT.slice(0, 5))
        return { status: 'failed', reason: 'conexión cortada' }
      }
      writeFileSync(destination, content)
      return { status: 'fetched' }
    },
  }
}

describe('materializeArtifact', () => {
  test('una caché vacía descarga una vez, verifica y publica en la ruta por digest', async () => {
    const fetcher = fetcherWriting(CONTENT)
    const outcome = await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher })
    expect(outcome).toEqual({ status: 'fetched', path: cachedArtifactPath(cacheDir, SHA), sha256: SHA })
    expect(fetcher.calls).toHaveLength(1)
  })

  test('el sha256 devuelto es el medido sobre el archivo publicado, en los dos caminos', async () => {
    const fetched = await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher: fetcherWriting(CONTENT) })
    const cached = await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher: fetcherWriting(CONTENT) })
    for (const outcome of [fetched, cached]) {
      if (!('path' in outcome)) throw new Error(`se esperaba materialización, salió ${outcome.status}`)
      expect(outcome.sha256).toBe(createHash('sha256').update(readFileSync(outcome.path)).digest('hex'))
    }
    expect([fetched.status, cached.status]).toEqual(['fetched', 'cached'])
  })

  test('una caché correcta no descarga', async () => {
    writeFileSync(cachedArtifactPath(cacheDir, SHA), CONTENT)
    const fetcher = fetcherWriting(CONTENT)
    expect((await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher })).status).toBe('cached')
    expect(fetcher.calls).toHaveLength(0)
  })

  test('una caché con otro contenido no se usa: se reconstruye desde el artefacto', async () => {
    writeFileSync(cachedArtifactPath(cacheDir, SHA), 'otro contenido')
    const fetcher = fetcherWriting(CONTENT)
    expect((await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher })).status).toBe('fetched')
    expect(fetcher.calls).toHaveLength(1)
  })

  test('una descarga con otro contenido se rechaza y no deja caché válida', async () => {
    const outcome = await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher: fetcherWriting('contenido ajeno') })
    expect(outcome.status).toBe('rejected')
    expect(existsSync(cachedArtifactPath(cacheDir, SHA))).toBe(false)
    expect(readdirSync(cacheDir)).toEqual([])
  })

  test('una descarga que falla no deja ni caché válida ni parciales', async () => {
    const outcome = await materializeArtifact({ artifact: ARTIFACT, pinned: PINNED, cacheDir, fetcher: fetcherWriting(undefined) })
    expect(outcome.status).toBe('failed')
    expect(readdirSync(cacheDir)).toEqual([])
  })

  test('un artefacto fijado a otro blob que el del catálogo no se descarga', async () => {
    const fetcher = fetcherWriting(CONTENT)
    const outcome = await materializeArtifact({ artifact: ARTIFACT, pinned: { ...PINNED, blobDigest: `sha256:${'0'.repeat(64)}` }, cacheDir, fetcher })
    expect(outcome.status).toBe('rejected')
    expect(fetcher.calls).toHaveLength(0)
  })
})

